def rows(text, keys):
    result = {}
    for line in text.strip().splitlines():
        cells = line.split('|')
        assert len(cells) == len(keys)+1, line
        result[int(cells[0])] = dict(zip(keys, cells[1:]))
    return result

TRACES = rows(TRACE_TEXT, ['endpoint', 'symbol', 'dispatch', 'local', 'evidence'])
GATES = rows(GATE_TEXT, ['title', 'context', 'question', 'yes', 'no', 'boundary', 'terms'])
assert set(TRACES) == set(GATES) == set(range(8, 76))
